#include <iostream> #include <algorithm> #include <string> using namespace std; int main(){ string A, B; cin >> A >> B; int i; if(A.size() > B.size()){ cout << "GREATER\ "; return 0; }else if (A.size() < B.size()){ cout << "LESS\ "; }else { for(i = 0; i < A.size(); i++){ if(A[i] > B[i]){ cout << "GREATER\ "; return 0; }else if(A[i] < B[i]){ cout << "LESS\ "; return 0; } } cout << "EQUAL\ "; return 0; } }'